"""Scientific figures and an offline report from actual xv6 UART measurements."""
import base64
from html import escape
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from .runtime import ROOT,VARIANTS,write_json


def build_report(directory):
    root=Path(directory);read=lambda name:json.loads((root/name).read_text());rows=read('raw_runs.json');env=read('environment.json');protocol=read('protocol.json')
    validation=json.loads((ROOT/'validation/kernel_validation.json').read_text());figures=root/'figures';figures.mkdir(exist_ok=True)
    kinds=list(protocol['workload_iterations']);alloc=('pages','fork','pipes');cache=('hotseq','hotrand','scan');variants=list(VARIANTS);colors=('#8c7865','#087f8c','#d88a35','#7162a6');labels=('Baseline','Per-CPU','Hash','Combined');median=lambda x:float(np.median(x))
    summary=[]
    for kind in kinds:
        base=[r for r in rows if r['kind']==kind and r['variant']=='baseline'];base_time=median([r['guest_seconds'] for r in base]);base_probe=median([r['probes']/r['lookups'] for r in base]) if kind in cache else None
        for variant in variants:
            samples=[r for r in rows if r['kind']==kind and r['variant']==variant];seconds=median([r['guest_seconds'] for r in samples])
            probes=median([r['probes']/r['lookups'] for r in samples]) if kind in cache else None
            summary.append({'kind':kind,'variant':variant,'operations':samples[0]['ops'],'median_guest_s':seconds,'min_guest_s':min(r['guest_seconds'] for r in samples),'max_guest_s':max(r['guest_seconds'] for r in samples),'speedup':base_time/seconds,
                'median_allocator_spins':median([r['aspins'] for r in samples]),'failed_exchanges_per_1000_ops':median([1000*r['aspins']/r['ops'] for r in samples]),'median_steals':median([r['steals'] for r in samples]),
                'median_allocator_acquires':median([r['alocks'] for r in samples]),'probes_per_lookup':probes,'probe_reduction':1-probes/base_probe if probes is not None else None,
                'cache_miss_fraction':median([r['misses']/r['lookups'] for r in samples]) if kind in cache else None})
    lookup={(r['kind'],r['variant']):r for r in summary};plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.18,'axes.titleweight':'bold','figure.dpi':125});files=[]
    def save(fig,name):fig.tight_layout();fig.savefig(figures/name,bbox_inches='tight');plt.close(fig);files.append(name)
    fig,axes=plt.subplots(1,2,figsize=(11,4.2))
    for index,variant in enumerate(variants):
        axes[0].bar(np.arange(3)+(index-1.5)*.19,[lookup[k,variant]['failed_exchanges_per_1000_ops'] for k in alloc],width=.19,color=colors[index],label=labels[index])
        axes[1].bar(np.arange(3)+(index-1.5)*.19,[lookup[k,variant]['median_steals'] for k in alloc],width=.19,color=colors[index],label=labels[index])
    axes[0].set_ylabel('Failed allocator exchanges / 1,000 work units');axes[0].set_title('Measured lock contention');axes[1].set_ylabel('Median batch-steal events');axes[1].set_title('Local allocation with steal-on-empty')
    for ax in axes:ax.set_xticks(range(3),['Page batches','Fork/exit','Pipe churn']);ax.legend(fontsize=8)
    save(fig,'allocator.png')
    fig,axes=plt.subplots(1,2,figsize=(11,4.2))
    for index,variant in enumerate(variants):
        axes[0].bar(np.arange(3)+(index-1.5)*.19,[lookup[k,variant]['probes_per_lookup'] for k in cache],width=.19,color=colors[index],label=labels[index])
        axes[1].bar(np.arange(3)+(index-1.5)*.19,[100*lookup[k,variant]['cache_miss_fraction'] for k in cache],width=.19,color=colors[index],label=labels[index])
    axes[0].set_ylabel('Candidate buffers examined / lookup');axes[0].set_title('Lookup work under the cache lock');axes[1].set_ylabel('Miss fraction (%)');axes[1].set_title('Same capacity and LRU policy')
    for ax in axes:ax.set_xticks(range(3),['Hot sequential','Two hot streams','Over-capacity scan']);ax.legend(fontsize=8)
    save(fig,'cache.png')
    fig,axes=plt.subplots(1,2,figsize=(11,4.2))
    for ax,selection,title in zip(axes,(alloc,cache),('Allocator/process workloads','Buffer-cache workloads')):
        for index,variant in enumerate(variants):ax.bar(np.arange(3)+(index-1.5)*.19,[lookup[k,variant]['speedup'] for k in selection],width=.19,color=colors[index],label=labels[index])
        ax.axhline(1,ls=':',color='#444');ax.set_xticks(range(3),selection);ax.set_ylabel('Baseline median elapsed / variant median elapsed');ax.set_title(title);ax.legend(fontsize=8)
    save(fig,'elapsed.png')
    def table(head,data):return '| '+' | '.join(head)+' |\n| '+' | '.join(['---']*len(head))+' |\n'+''.join('| '+' | '.join(map(str,row))+' |\n' for row in data)
    def picture(name,caption):return f'![{caption}](figures/{name})\n\n{caption}'
    sections=[]
    def add(title,body):sections.append((title,body))
    add('Track G: xv6 Operating-System Optimization','Prepared for Akshat Tikaria, roll number 241070005. Assignment 8.\n\nThis package modifies and boots the real MIT xv6 RISC-V kernel in QEMU. It implements per-CPU physical-page allocation with batch stealing, and a hash index for buffer lookup while retaining the original global cache lock and LRU replacement. Measurements come from new guest programs and raw UART logs. They are emulated guest results, not a native laptop or production-OS speed claim.')
    page_base=lookup['pages','baseline'];page_cpu=lookup['pages','percpu']
    add('Main measured findings',f'The allocator-only page workload reduced median failed exchanges from {page_base["median_allocator_spins"]:,.0f} to {page_cpu["median_allocator_spins"]:,.0f}, but elapsed time increased from {page_base["median_guest_s"]:.4f} to {page_cpu["median_guest_s"]:.4f} seconds ({page_cpu["median_guest_s"]/page_base["median_guest_s"]:.2f} times slower). Thus the contention objective improved while end-to-end elapsed performance regressed sharply. The cause of that regression has not been isolated; zero measured spinning does not mean the implementation is fast.\n\n'+table(['Hash-only cache workload','Lookup-probe reduction','Elapsed ratio vs baseline'],[[k,f'{lookup[k,"hash"]["probe_reduction"]:.2%}',f'{lookup[k,"hash"]["speedup"]:.3f}'] for k in cache])+'\nHashing reduces search work in every cache workload. Miss fractions remain the same in the recorded runs. Timing benefits are smaller and workload-dependent, including a negative elapsed result for the two-stream case; three emulated repetitions do not prove a statistically significant native speedup. All slow configurations and all repetitions remain in the report.')
    add('Source, setup and validation',f'Official xv6 commit: e93dabeb98431235c6e1a101cb96c73c923fdbc4. All 82 upstream Git blob hashes were verified; the original MIT license is retained. Toolchain: {env["versions"]["qemu-system-riscv64"]}; {env["versions"]["riscv64-linux-gnu-gcc"]}. Each measured guest has {env["guest_cpus"]} vCPUs and 128 MiB RAM. No KVM, GPU or network device is required.\n\n'+table(['Configuration','Per-CPU allocator','Hash lookup','Full upstream usertests','Custom checks'],[[r['variant'],VARIANTS[r['variant']][0],VARIANTS[r['variant']][1],f'{len(r["test_names"])} named tests: PASS','Before/after: PASS'] for r in validation])+'\nThe pristine unmodified kernel also passed all 74 named tests. These runs include the slow tests, not just usertests -q. Intentional invalid-memory tests print traps and out-of-space messages; the final ALL TESTS PASSED result and complete named-test set establish success. gcheck additionally validates free-list uniqueness/counts, cache-key uniqueness, LRU/hash membership, page contents, statistics ABI and invalid user destinations. This is finite correctness evidence, not a formal race-freedom proof or a KCSAN run.')
    add('Optimization and invariants',table(['Feature','Decision and objective','Preserved invariant'],[
        ['Per-CPU pages','Prefer a local free list; steal at most 32 pages only when empty. Reduce shared-lock contention.','Pin cpuid with interrupts disabled; detach under victim lock, publish extras under local lock; normal paths hold one allocator lock at a time.'],
        ['Buffer hash index','Search one of 13 buckets instead of scanning all 30 buffers. Reduce lookup comparisons under the existing lock.','Keys/hash/LRU/reference counts remain protected by bcache.lock; one cached buffer per device/block; only unreferenced buffers recycled.']])+'\nThe allocator uses dynamic load balancing through steal-on-empty, reusing the parallelism concepts from Chapter 6. Hash lookup changes the search structure, not cache capacity, eviction order, block contents, per-buffer sleep locking or log pinning. It is not a sharded or lock-free cache. Both changes have metadata and bookkeeping costs. The baseline disables both features but retains identical instrumentation/check interfaces; it is distinguished from the separately validated pristine kernel.')
    add('Six workloads and timing',table(['Kind','Recorded iterations','Work unit and checks'],[[k,protocol['workload_iterations'][k],{'pages':'Three workers; 16 eager pages/batch; verify first/last bytes before freeing.','fork':'Three workers repeatedly fork/wait; grandchild status checked.','pipes':'Three workers create/write/read/close pipes; every byte checked.','hotseq':'One warmed 16-block sequential file stream.','hotrand':'Pseudo-random interleaving of two warmed eight-block streams.','scan':'One 96-block file stream exceeds the 30-buffer cache.'}[k]] for k in kinds])+f'\nThere are {len(rows)} measured runs over four configurations and {protocol["repeats"]} repetitions, with a fresh filesystem image/boot per configuration and repetition. Workload order is deterministically shuffled and matched by repetition. All six workloads finish with invariants checked. Cache setup/sync/warmup and file cleanup lie outside the measured interval. Worker creation/readiness is outside the allocator interval; work, exit and reaping are inside it. This explains why frees can exceed measured allocations: the initial worker copies are freed inside the interval.\n\nElapsed time uses guest r_time, with a frequency of {env["timebase_frequency_hz"]:,} Hz read from QEMU’s device tree. This is a virtual time counter, not retired CPU cycles. Snapshot overhead and observation-lock acquisitions remain included. Host command latency includes setup and output and is retained only as ancillary evidence. Shared-host scheduling and QEMU overhead limit performance generalization; three repeats do not establish statistical significance.')
    add('Allocator contention and balancing',picture('allocator.png','Failed atomic exchanges count spins after losing the allocator lock. A zero baseline is reported as zero rather than an invented percentage improvement. Work units differ across the three workloads.')+'\n'+table(['Workload','Configuration','Median failed exchanges','Allocator lock acquisitions','Batch steals'],[[k,v,f'{lookup[k,v]["median_allocator_spins"]:.0f}',f'{lookup[k,v]["median_allocator_acquires"]:.0f}',f'{lookup[k,v]["median_steals"]:.0f}'] for k in alloc for v in variants])+'\nFewer failed exchanges support a contention claim only for the measured workload. A speed benefit does not follow automatically: page poisoning/zeroing, process-table locks, scheduling and batch-transfer overhead may dominate. Empty local lists can cause extra victim scans; free memory is shared through stealing rather than statically partitioned or lost.')
    add('Buffer lookup and miss behavior',picture('cache.png','Probes count cache lookup comparisons; miss fraction counts bget misses. Metadata lookups are included. The hot-stream and over-capacity cases expose distinct locality conditions.')+'\n'+table(['Workload','Configuration','Probes/lookup','Probe reduction vs baseline','Miss fraction'],[[k,v,f'{lookup[k,v]["probes_per_lookup"]:.3f}',f'{lookup[k,v]["probe_reduction"]:.2%}',f'{lookup[k,v]["cache_miss_fraction"]:.2%}'] for k in cache for v in variants])+'\nA smaller lookup search does not imply fewer disk reads. The capacity and LRU policy are unchanged, so a scan can continue missing heavily while doing less comparison work. The global cache lock remains; any contention or parallel scalability claim is limited accordingly. Hash collisions and uneven bucket occupancy remain possible.')
    add('Measured elapsed-time trade-offs',picture('elapsed.png','Ratios use all repetitions’ medians for the same workload. Values below one are slowdowns and remain in the data.')+'\n'+table(['Workload','Configuration','Median guest seconds','Min–max guest seconds','Elapsed ratio'],[[r['kind'],r['variant'],f'{r["median_guest_s"]:.5f}',f'{r["min_guest_s"]:.5f}–{r["max_guest_s"]:.5f}',f'{r["speedup"]:.3f}'] for r in summary])+'\nInterpret elapsed time together with lock/probe counts and raw spread. Emulation, scheduling, disk service and memory clearing can outweigh the targeted savings. These ratios are neither native host parallel speedups nor guarantees for other machines, cache sizes or workloads. No slow or inconvenient run has been replaced by theoretical values.')
    add('Verification, AI correction and remaining scope','The audit matches every numeric record to raw UART output, checks work units/feature flags/time conversion, verifies source/UART hashes and confirms the complete upstream test sets for all configurations. Host parser/provenance tests are additional checks and are kept separate from real guest usertests. The patch is included and checked against the exact pristine snapshot.\n\nA real AI-generated compatibility error used an older four-argument copyout call. The pinned xv6 API requires five arguments, including process size for lazy-memory bounds. The compiler rejected it; the fix supplies p->sz. The original build failure, original/fix commits and invalid-destination guest check are retained. No manual student correction or independent second-AI-tool comparison is claimed.\n\nTwo kernel features and six workloads satisfy Track G’s core scope. H (DBMS), I (remaining quantum/QML), J (software engineering), the combined submission, outstanding research reproductions, full chat exports, second-tool comparison, public repository and live demonstration remain open. Earlier packages are preserved. No production security or formal verification claim is made.')
    add('Primary references','- Official xv6 source and MIT license: https://github.com/mit-pdos/xv6-riscv\n- Pinned commit: https://github.com/mit-pdos/xv6-riscv/commit/e93dabeb98431235c6e1a101cb96c73c923fdbc4\n- MIT tools: https://pdos.csail.mit.edu/6.1810/2025/tools.html\n- MIT lock lab, per-CPU free-list/stealing concepts: https://pdos.csail.mit.edu/6.1810/2025/labs/lock.html\n- Supplied Assignment 8 Track G. References accessed 2026-11-04. These measurements are this project’s own; MIT’s illustrative results are not reused.')
    (root/'REPORT.md').write_text('\n\n'.join('# '+title+'\n\n'+body for title,body in sections)+'\n')
    def render(body):
        lines=body.splitlines();out=[];i=0
        while i<len(lines):
            line=lines[i]
            if line.startswith('| '):
                data=[]
                while i<len(lines) and lines[i].startswith('| '):data.append([v.strip() for v in lines[i].strip('|').split('|')]);i+=1
                out.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+escape(v)+'</th>' for v in data[0])+'</tr></thead><tbody>')
                for row in data[2:]:out.append('<tr>'+''.join('<td>'+escape(v)+'</td>' for v in row)+'</tr>')
                out.append('</tbody></table></div>');continue
            if line.startswith('!['):
                name=line.split('(figures/',1)[1].rstrip(')');encoded=base64.b64encode((figures/name).read_bytes()).decode();out.append('<img alt="'+escape(line[2:line.index(']')])+'" src="data:image/png;base64,'+encoded+'">')
            elif line:out.append('<p>'+escape(line)+'</p>')
            i+=1
        return '\n'.join(out)
    html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track G xv6 Optimization</title><style>body{margin:0;background:#edf3f5;color:#19353f;font:16px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:32px auto;background:white;padding:36px;border-top:8px solid #087f8c;border-radius:12px}h1{font-size:32px;line-height:1.2}h2{font-size:24px;color:#075e68;margin-top:42px}img{width:100%;height:auto;margin:18px 0}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;border-bottom:1px solid #dce6e9;text-align:left}th{background:#e8f2f3}p{overflow-wrap:anywhere}@media(max-width:700px){main{margin:0;padding:20px}}</style><main>'
    for i,(title,body) in enumerate(sections):tag='h1' if i==0 else 'h2';html+='<'+tag+'>'+escape(title)+'</'+tag+'>'+render(body)
    (root/'report.html').write_text(html+'</main></html>');write_json(root/'summary.json',summary);return files
